import re


class SplitSentence:

    SENTENCE_SPLIT_PATTERN = r'(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s'
    NON_ALPHABETIC_PATTERN = r'[^a-zA-Z\s]'

    def __init__(self):
        self._sentences_string = None

    @property
    def sentences_string(self):
        return self._sentences_string

    @sentences_string.setter
    def sentences_string(self, value):
        self._sentences_string = value

    def split_sentences(self):
        if not self._sentences_string:
            return []
        sentences = re.split(self.SENTENCE_SPLIT_PATTERN, self._sentences_string)
        return sentences

    def count_words(self, sentence):
        cleaned_sentence = re.sub(self.NON_ALPHABETIC_PATTERN, '', sentence)
        words = cleaned_sentence.split()
        return len(words)

    def find_max_word_count(self):
        sentences = self.split_sentences()
        return max((self.count_words(sentence) for sentence in sentences), default=0)

    def process_text_file(self, sentences_string):
        self.sentences_string = sentences_string
        return self.find_max_word_count()
